using System.Security.Cryptography;
using System.Text;
using Orbit.Core;
static class InstallerChecks {
 sealed class ProgressLog:IProgress<InstallProgress>{readonly string path;long last;public ProgressLog(string p){path=p;}public void Report(InstallProgress p){if(Environment.TickCount64-last<1200&&p.Done!=p.Total)return;last=Environment.TickCount64;string text=$"{p.Stage}: {p.Percent:0.0}% {p.Done}/{p.Total} bytes; {p.Files}/{p.TotalFiles} files";Console.WriteLine(text);File.WriteAllText(path,text);if(p.Total>0&&p.Percent>5&&p.Percent<95){string sample=Path.Combine(Path.GetDirectoryName(path)!,"download-progress.json");if(!File.Exists(sample))File.WriteAllText(sample,System.Text.Json.JsonSerializer.Serialize(p));}}}
 sealed class CancelOnBytes:IProgress<InstallProgress>{readonly CancellationTokenSource c;public CancelOnBytes(CancellationTokenSource value){c=value;}public void Report(InstallProgress p){if(p.Done>262144)c.Cancel();}}
 public static int Run(string root){try{RunAsync(root).GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static async Task RunAsync(string root){Directory.CreateDirectory(root);using var service=new MojangInstaller(Path.Combine(root,"catalog"));var list=await service.CatalogAsync();if(list.Count<100)throw new Exception("Catalog incomplete");
 foreach(string bad in new[]{"http://piston-data.mojang.com/a","https://evil.example/a","https://piston-data.mojang.com.evil.example/a","https://piston-data.mojang.com:8443/a"}){try{MojangInstaller.OfficialUri(bad);throw new Exception("Accepted untrusted URL");}catch(InvalidDataException){}}
 string marker=Path.Combine(root,"runtime","jre-legacy",".orbit-installing");Directory.CreateDirectory(Path.GetDirectoryName(marker)!);File.WriteAllText(marker,"Force test of official Java installation");var remote=list.Single(v=>v.Id=="1.7.10");Console.WriteLine("Real Mojang installation to isolated test root: "+root);var reports=new ProgressLog(Path.Combine(root,"test-progress.txt"));await service.InstallAsync(root,remote,reports);
 var settings=new LauncherSettings{GameRoot=root,Nickname="OrbitTester",Isolated=true};var plan=LaunchEngine.Build(settings,remote.Id);if(plan.Missing.Count!=0)throw new Exception("Installed files missing: "+string.Join(";",plan.Missing));if(LaunchEngine.CheckAssets(settings,plan).Count!=0)throw new Exception("Assets incomplete");if(!Path.GetFullPath(plan.Java).StartsWith(Path.GetFullPath(root),StringComparison.OrdinalIgnoreCase))throw new Exception("Runtime not installed into test root");if(LaunchEngine.ReadJava(plan.Java)?.Major!=8)throw new Exception("Java 8 not installed");
 var javaProbe=new LaunchPlan{Version=plan.Version,Java=plan.Java,GameDirectory=root,Natives=Path.Combine(root,"probe")};javaProbe.Arguments.Add("-version");using(var process=LaunchEngine.Start(javaProbe)){process.StandardError.ReadToEnd();process.StandardOutput.ReadToEnd();await process.WaitForExitAsync();if(process.ExitCode!=0)throw new Exception("Downloaded Java 8 cannot execute");}Console.WriteLine("PASS complete client, libraries, resources, virtual asset mapping and automatic Java 8; Java probe executed; game not launched");
 // Exercise byte-range resume against Mojang, preserving verified final files.
 string jar=Path.Combine(root,"versions","1.7.10","1.7.10.jar");byte[] content=await File.ReadAllBytesAsync(jar);string metadata=Path.Combine(root,"versions","1.7.10","1.7.10.json");var d=System.Text.Json.Nodes.JsonNode.Parse(await File.ReadAllTextAsync(metadata))!;string resume=Path.Combine(root,"resume-client.jar");await File.WriteAllBytesAsync(resume+".orbit-part",content[..1048576]);var job=new DownloadFile(resume,d["downloads"]!["client"]!["url"]!.ToString(),Convert.ToHexString(SHA1.HashData(content)),content.Length);long bytes=0;await service.DownloadAsync(job,n=>bytes+=n);if(bytes!=content.Length||!await MojangInstaller.IsValidAsync(job))throw new Exception("Range resume failed");Console.WriteLine("PASS resumed Mojang client download; SHA-1 verified");
 // A checksum failure must never publish the destination.
 string badPath=Path.Combine(root,"bad-hash.bin");var invalid=job with{Path=badPath,Sha1=new string('0',40)};bool rejected=false;try{await service.DownloadAsync(invalid);}catch(IOException){rejected=true;}if(!rejected||File.Exists(badPath))throw new Exception("Corrupt download published");Console.WriteLine("PASS checksum mismatch rejected without publishing final file");
 using(var canceled=new CancellationTokenSource()){canceled.Cancel();bool stopped=false;try{await service.DownloadAsync(job with{Path=Path.Combine(root,"cancel.bin")},ct:canceled.Token);}catch(OperationCanceledException){stopped=true;}if(!stopped)throw new Exception("Cancellation failed");}Console.WriteLine("PASS cancellation");
 using(var cancelInstall=new CancellationTokenSource()){var other=list.Single(v=>v.Id=="1.21.11");bool stopped=false;try{await service.InstallAsync(root,other,new CancelOnBytes(cancelInstall),cancelInstall.Token);}catch(OperationCanceledException){stopped=true;}if(!stopped||File.Exists(Path.Combine(root,"versions",other.Id,other.Id+".json")))throw new Exception("Canceled install published metadata");Console.WriteLine("PASS in-flight install cancellation without publishing an incomplete version");}
 await service.InstallAsync(root,remote,reports);Console.WriteLine("PASS repeat install reuses validated files");
 }
}
